/* prog59_rule110.c – reproduces the behaviour of the supplied binary.
 *
 * The program implements elementary cellular automaton Rule 110.
 *
 * Usage:
 *   prog59_rule110 <binary‑string> <steps>
 *
 *   <binary‑string> : a non‑empty string of ‘0’ and ‘1’, length ≤ 60
 *   <steps>         : a non‑negative integer (the original binary caps it at 200)
 *
 * If the arguments are missing, malformed, or out of the allowed range,
 * the program prints the single line
 *
 *     INVALID_INPUT
 *
 * and terminates.
 *
 * For valid input the program prints the initial configuration followed
 * by <steps> further generations (i.e. <steps>+1 lines in total), each line
 * terminated by a newline.  The length of the configuration is limited to
 * 60 cells – the same limit used by the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN   60          /* size of the static buffers in the original binary */
#define MAX_STEPS 200         /* hard limit imposed by the original binary */

/* Rule 110 lookup table.
 * Index = (left << 2) | (center << 1) | right   (binary 0‑7)
 * Value = resulting cell ('0' or '1')
 *
 * 111 → 0   (7)
 * 110 → 1   (6)
 * 101 → 1   (5)
 * 100 → 0   (4)
 * 011 → 1   (3)
 * 010 → 1   (2)
 * 001 → 1   (1)
 * 000 → 0   (0)
 */
static const char rule110[8] = {
    '0', /* 000 */
    '1', /* 001 */
    '1', /* 010 */
    '1', /* 011 */
    '0', /* 100 */
    '1', /* 101 */
    '1', /* 110 */
    '0'  /* 111 */
};

/* Return 1 if the string consists only of ‘0’ and ‘1’, otherwise 0. */
static int is_binary_string(const char *s, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        if (s[i] != '0' && s[i] != '1')
            return 0;
    return 1;
}

/* Compute the next generation of a row using Rule 110. */
static void next_row(const char *cur, char *nxt, size_t len)
{
    for (size_t i = 0; i < len; ++i) {
        int left   = (i == 0)     ? 0 : (cur[i - 1] - '0');
        int center = cur[i] - '0';
        int right  = (i == len-1) ? 0 : (cur[i + 1] - '0');

        int idx = (left << 2) | (center << 1) | right;
        nxt[i] = rule110[idx];
    }
}

/* Print a row followed by a newline. */
static void print_row(const char *row, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        putchar(row[i]);
    putchar('\n');
}

int main(int argc, char **argv)
{
    /* ----- argument count check ----- */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- first argument: initial configuration ----- */
    const char *init = argv[1];
    size_t len = strlen(init);

    if (len == 0 || len > MAX_LEN || !is_binary_string(init, len)) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- second argument: number of generations ----- */
    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);

    if (endptr == argv[2] || *endptr != '\0' || steps < 0) {
        puts("INVALID_INPUT");
        return 0;
    }

    if (steps > MAX_STEPS)
        steps = MAX_STEPS;          /* cap to 200 as in the original binary */

    /* ----- buffers for the current and next generation ----- */
    char cur[MAX_LEN];
    char nxt[MAX_LEN];

    memcpy(cur, init, len);

    /* ----- print the initial configuration ----- */
    print_row(cur, len);

    /* ----- main loop: generate and print the requested number of generations ----- */
    for (long gen = 0; gen < steps; ++gen) {
        next_row(cur, nxt, len);
        memcpy(cur, nxt, len);
        print_row(cur, len);
    }

    return 0;
}
